pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: send 2 ether to c via Put with unlock time 0, so it's immediately collectable
        vm.deal(address(this), 2 ether);
        c.Put{value: 2 ether}(0);
        // Warp past block.timestamp to ensure unlock time is passed
        vm.warp(block.timestamp + 1);
        // Try to Collect 1 ether (less than balance, meets MinSum)
        c.Collect(1 ether);
        // After Collect, the balance should be 1 ether (2 initial - 1 collected)
        // Reference: Collect succeeds, bug: Collect reverts due to > in Put
        // The bug causes a revert, but we catch it via try/catch
        bool ok;
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        try c.Put{value: 1 ether}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: Put succeeds (balance 1 + 1 >= 1) => ok=true, bug: Put fails (1+1 > 1?) Actually 1+1 > 1 is true, so both succeed for this. Need different scenario.
        // Let's use a scenario where reference succeeds and bug fails due to overflow check
        // Better: after Collect, balance is 1. Then call Put with 0 value, which should succeed in reference but fail in bug because require(1+0 > 1) is false
        bool ok2;
        vm.deal(address(this), 0 ether);
        vm.prank(address(this));
        try c.Put{value: 0 ether}(0) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        // Reference: ok2 = true (1+0 >= 1), Bug: ok2 = false (1+0 > 1 is false)
        assertTrue(ok2);
    }
}

