pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user sends 1 wei via fallback (Put(0))
        vm.deal(address(1), 1 ether);
        vm.prank(address(1));
        (bool ok,) = address(c).call{value: 1}("");
        assertTrue(ok);

        // Warp past unlockTime (0 since block.timestamp used in fallback)
        // Actually unlockTime set to block.timestamp at call time; warp forward
        vm.warp(block.timestamp + 1);

        // The reference has balance = 1, buggy has balance = 2.
        // MinSum is 1 ether (1000000000000000000 wei).
        // For the reference, acc.balance (1) < MinSum so Collect reverts.
        // For the buggy, acc.balance (2) < MinSum also reverts.
        // To diverge: we need balance >= MinSum. Let's first do a Put with large unlockTime.
        vm.deal(address(1), 10 ether);
        vm.prank(address(1));
        c.Put{value: 1 ether}(block.timestamp + 100);

        // Now reference balance = 1 ether + 1 wei? No, fallback gave 1 wei, Put gave 1 ether. Reference: 1000000000000000001. Buggy: 1000000000000000002.
        // Warp to after unlockTime
        vm.warp(block.timestamp + 101);

        // Now try to Collect 1 ether (1000000000000000000 wei).
        // Reference: balance >= MinSum (1000000000000000000) yes, balance >= _am yes, timestamp > unlockTime yes => succeeds, resulting balance = 1000000000000000001 - 1000000000000000000 = 1.
        // Buggy: same but ending balance = 2.
        vm.prank(address(1));
        c.Collect(1 ether);

        // Assert that final balance is 1 (reference) vs 2 (buggy).
        (uint unlockTime, uint balance) = c.Acc(address(1));
        assertEq(balance, 1);
    }
}

