import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: Alice puts 2 ether with unlock time far in the future
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Put{value: 2 ether}(block.timestamp + 1000);

        // Warp to a time strictly after unlock (block.timestamp > unlockTime)
        vm.warp(block.timestamp + 5000);

        // Now Alice tries to collect 2 ether (her full balance)
        // The reference version should succeed (allow withdrawal)
        // The buggy version uses >= for unlock check, so it would succeed too
        // But the difference? Actually both succeed. Let's adjust:
        // We want a case where >= breaks the expected behavior.
        // With reference: block.timestamp > unlockTime required
        // With bug: block.timestamp >= unlockTime required.
        // If we set unlock time exactly equal to block.timestamp, reference reverts, buggy succeeds.
        // That is a divergence.
        // But we need a scenario where the reference satisfies an assertion and the bug breaks it.
        // So let assertion be: calling Collect returns true (no revert) from a try/catch.
        // Setup: Alice puts 2 ether with unlockTime = block.timestamp + 100
        // Warp to exactly block.timestamp + 100 (i.e., unlockTime == block.timestamp).
        // The reference will revert (requires >), the bug will succeed (requires >=).
        // So we assert that the call reverts (ok == false). Reference: ok == false -> assertTrue(!ok) passes.
        // Buggy: ok == true -> assertTrue(!ok) fails.

        // Reset for clean scenario:
        // (We'll just use a new deploy? We can't, but we can reuse with fresh state after previous call?)
        // Better: create fresh deploy in test.
    }
}

